# -*- coding: utf-8 -*-
css=open("css.txt").read()+".chip{display:inline-block;border:1px solid #243134;border-radius:10px;padding:8px 12px;font-size:13px;color:#8DA09D;margin:0 6px 6px 0}.chip.on{background:#123B35;color:#45D0BB;border-color:#45D0BB}.sec{font-size:12px;letter-spacing:.12em;color:#8DA09D;font-weight:600}.row{display:flex;gap:12px;align-items:center;padding:12px 4px;border-bottom:1px solid #243134}.av{width:40px;height:40px;border-radius:50%;background:#1B2629;display:flex;align-items:center;justify-content:center;font-weight:600;color:#45D0BB}.dlg{background:#151E20;border:1px solid #243134;border-radius:20px;padding:20px;margin-top:6px}.opt{display:flex;gap:12px;align-items:center;padding:10px 0;font-size:16px}.rad{width:20px;height:20px;border-radius:50%;border:2px solid #8DA09D}.rad.on{border-color:#45D0BB;background:radial-gradient(#45D0BB 45%,transparent 50%)}"
def phone(inner,title,back=True):
    return f'<div class="ph"><div class="sb"><span>9:41</span><span>Tor · 5G</span></div><div class="bar">{"<span>←</span>" if back else ""}{title}</div>{inner}</div>'
def page(s): return f"<!doctype html><meta charset=utf-8><style>{css}</style>{s}"
OUT={}
# ---- business (English interface, as the app is today) ----
qr='<div class="qr" style="width:170px;height:170px;border-style:solid;border-width:2px;color:#45D0BB;font-size:60px">▣</div>'
OUT["biz_1"]=phone('<div class="body"><div>'+'<span class="chip">Android contact</span><span class="chip">iOS / cross-platform</span><span class="chip on">Business (Node-Mesh)</span></div><div class="sec">YOUR CODE</div>'+qr+'<div class="dim" style="text-align:center">tor active — your code is ready</div><div style="flex:1"></div><div class="btn">Scan their code</div></div>',"Add contact")
msgs=[("in","Can you send the signed contract today?"),("out","Yes, in the next hour."),("in","Thanks. Please use the usual route."),("out","Understood.")]
bub="".join(f'<div class="bub {d}">{x}</div>' for d,x in msgs)
OUT["biz_2"]=phone(f'<div class="body" style="gap:10px"><div class="dim" style="text-align:center;font-size:12px">End-to-end encrypted • tap to rename</div>{bub}<div style="flex:1"></div><div class="fld">Message…</div></div>',"Mihai · Legal")
OUT["biz_3"]=phone(f'<div class="body" style="gap:10px"><div class="bub in">Can you send the signed contract today?</div><div class="bub out">Yes, in the next hour.</div><div class="dlg"><div style="font-size:19px;font-weight:600;margin-bottom:8px">How long may packets wait?</div><div class="dim" style="font-size:13px">Your packets for this chat are deleted from the nodes after this time, at the latest after 24 hours.</div><div class="opt"><div class="rad"></div>1 hour(s)</div><div class="opt"><div class="rad on"></div>6 hour(s)</div><div class="opt"><div class="rad"></div>24 hour(s)</div></div></div>',"Mihai · Legal")
# ---- press (own wording, English and Romanian) ----
P={"en":dict(t1="Send a tip safely",b1="Scan the journalist's QR code. You only do this once — no name, no phone number, no account.",scan="Scan QR code",paste="…or paste the code",conn="Connect",num="Tip number",st="Received and confirmed",s=("Received","Review","Closed"),opened="Received on 12 Oct 2026",last="Last update: today, 10:42",hint="Changes from the newsroom appear here automatically. Your tip number is only for you: it helps you refer to your tip, it is not needed to log in. There is no deadline for an answer: a journalist may or may not reply.",tabs=("Status","Messages"),m=[("in","Thank you. We received your tip and are looking at it."),("out","Can I add a photo?"),("in","Yes, please. Your name is not needed.")],ph="Message…"),
   "ro":dict(t1="Trimite un pont în siguranță",b1="Scanează codul QR al jurnalistului. Faci asta o singură dată — fără nume, fără număr de telefon, fără cont.",scan="Scanează codul QR",paste="…sau lipește codul",conn="Conectează",num="Număr pont",st="Primită și confirmată",s=("Primită","Analiză","Închis"),opened="Primită la 12 oct 2026",last="Ultima actualizare: azi, 10:42",hint="Modificările făcute de redacție apar aici automat. Numărul pontului este doar pentru tine: te ajută să te referi la pont, nu este necesar pentru autentificare. Nu există un termen de răspuns: un jurnalist poate răspunde sau nu.",tabs=("Stare","Mesaje"),m=[("in","Mulțumim. Am primit pontul și îl analizăm."),("out","Pot adăuga o poză?"),("in","Da, vă rugăm. Nu este nevoie de numele dumneavoastră.")],ph="Mesaj…")}
for L,t in P.items():
    OUT[f"press_{L}_1"]=phone(f'<div class="body" style="justify-content:center"><div style="font-size:30px;font-weight:700;line-height:1.15">{t["t1"]}</div><div class="dim" style="font-size:16px">{t["b1"]}</div><div class="qr">▣</div><div class="btn">{t["scan"]}</div><div class="dim" style="text-align:center">{t["paste"]}</div><div class="fld">unpruuf-…</div><div class="btn2">{t["conn"]}</div></div>',"unpruuf",False)
    tabs=f'<div class="tabs"><div class="a">{t["tabs"][0]}</div><div>{t["tabs"][1]}</div></div>'
    OUT[f"press_{L}_3"]=phone(tabs+f'<div class="body"><div class="card"><div class="dim">{t["num"]}</div><div class="big">HW-9D2W-6T4B</div></div><div class="card"><div style="font-size:18px;font-weight:600;margin-bottom:10px">{t["st"]}</div><div class="step"><div class="dot on">✓</div><div class="ln lon"></div><div class="dot on">✓</div><div class="ln"></div><div class="dot"></div></div><div class="lab"><span>{t["s"][0]}</span><span>{t["s"][1]}</span><span>{t["s"][2]}</span></div></div><div class="card dim">{t["opened"]}<br>{t["last"]}</div><div class="dim" style="font-size:13px">{t["hint"]}</div></div>',"HW-9D2W-6T4B")
for k,v in OUT.items(): open(f"{k}.html","w",encoding="utf-8").write(page(v))
print(list(OUT))
